import {baseUri} from '@jetbrains/teamcity-ui'
import type {KeyboardEvent} from 'react'
import {useSearchParams} from 'react-router'

import {useQueryParam, useQueryParamState} from '../../../../../../hooks/routes'
import {stringifyId, toProjectId} from '../../../../../../types'
import type {VcsProvider} from '../../../services/pipelinesApi.types'
import {VcsProviderType} from '../../../services/pipelinesApi.types'
import {isPipelinesEnabledInExclusiveMode} from '../../../utils/featureToggles'
import {getExternalVcsRootEditUrl, loginToVcsProvider} from '../../../utils/vcs'
import VcsProviderIcon from '../../VcsProviderIcon/VcsProviderIcon'

import styles from './VcsLoginItem.module.css'

type Props = {
  vcsProvider: VcsProvider
  onLogin?: (value?: VcsProvider) => void
}

const baseAdminUrl = `${baseUri}/admin`
const baseUrlToVcsConnectionAdminPage = `${baseAdminUrl}/editProject.html?tab=oauthConnections`

function VcsLoginItem({vcsProvider, onLogin}: Props) {
  const [projectIdQueryParam] = useQueryParamState('projectId', null)
  const createPipelinePageMode = useQueryParam('mode')
  const isLoginScreenMode = createPipelinePageMode === 'loginScreen'
  const projectId = toProjectId(stringifyId(projectIdQueryParam))
  const [searchParams, setSearchParams] = useSearchParams()

  const handleLogin = () => {
    if (isPipelinesEnabledInExclusiveMode()) {
      if (vcsProvider.connectionId) {
        loginToVcsProvider(vcsProvider.connectionId, projectId, onLogin)
      } else {
        onLogin?.(vcsProvider)
      }
    } else if (vcsProvider.type === VcsProviderType.ANY) {
      if (isLoginScreenMode) {
        const searchParamsObject = Object.fromEntries(searchParams.entries())
        delete searchParamsObject.mode
        setSearchParams(searchParamsObject)
      }

      onLogin?.(vcsProvider)
    } else {
      const vcsProviderType = vcsProvider.type
      const isVcsProviderTypeConnectByRepositoryUrl =
        vcsProviderType === VcsProviderType.CONNECT_BY_REPOSITORY_URL
      const redirectUrlParams = `&projectId=${projectId}&selectedVcsProvider=${vcsProviderType}`
      const redirectUrlToToVcsConnectionAdminPage = `${baseUrlToVcsConnectionAdminPage}${redirectUrlParams}`
      const redirectUrlToToVcsRootAdminPage = getExternalVcsRootEditUrl(
        undefined,
        'addVcsRoot',
        {
          projectId,
          editingScope: `editProject:${projectId}`,
          selectedVcsProvider: vcsProviderType,
        },
        null,
      )
      location.href = isVcsProviderTypeConnectByRepositoryUrl
        ? redirectUrlToToVcsRootAdminPage
        : redirectUrlToToVcsConnectionAdminPage
    }
  }
  const handleKeyDown = ({key}: KeyboardEvent<HTMLDivElement>) => {
    if (key === 'Enter') {
      handleLogin()
    }
  }

  return (
    <div
      key={vcsProvider.connectionId}
      className={styles.vcsItem}
      role={'button'}
      tabIndex={0}
      onClick={handleLogin}
      onKeyDown={handleKeyDown}
    >
      <VcsProviderIcon className={styles.vcsIcon} vcsProviderType={vcsProvider.type} />
      <div>
        <span className={styles.vcsName}>{vcsProvider.displayName}</span>
        {vcsProvider.description && (
          <div className={styles.vcsDescription}>{vcsProvider.description}</div>
        )}
      </div>
    </div>
  )
}

export default VcsLoginItem
