import type {SkeletonThemeProps} from 'react-loading-skeleton'
import {SkeletonTheme} from 'react-loading-skeleton'

import 'react-loading-skeleton/dist/skeleton.css'

const skeletonBaseColor = 'rgb(var(--ring-tag-background-components))'
const skeletonHighlightColor = 'rgb(var(--ring-disabled-background-components))'
const skeletonBorderRadius = 'calc(var(--ring-unit) * 1.5)'

function SkeletonLoaderTheme({children, ...otherProps}: SkeletonThemeProps) {
  return (
    <SkeletonTheme
      borderRadius={skeletonBorderRadius}
      highlightColor={skeletonHighlightColor}
      baseColor={skeletonBaseColor}
      {...otherProps}
    >
      {children}
    </SkeletonTheme>
  )
}

export default SkeletonLoaderTheme
