import lockIcon from '@jetbrains/icons/lock.svg'
import ErrorMessage from '@jetbrains/ring-ui-built/components/error-message/error-message'
import Theme from '@jetbrains/ring-ui-built/components/global/theme'
import Loader from '@jetbrains/ring-ui-built/components/loader/loader'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {useState} from 'react'
import {type EntryPointProps, usePreloadedQuery} from 'react-relay'
import {useNavigate} from 'react-router'

import {useDarkOrLightTheme} from '../../../../hooks/theme/useDarkOrLightTheme'
import {getPipelineHref, getPipelinesHref} from '../../../../routes'
import PageTitle from '../../../common/PageTitle/PageTitle'
import Redirect from '../../../common/Redirect/Redirect'
import RouterLink from '../../../common/RouterLink/RouterLink'
import PipelineForm from '../components/PipelineForm/PipelineForm'
import RestScreenHeight from '../components/RestScreenHeight/RestScreenHeight'
import VcsLoginScreen from '../components/VcsLoginScreen/VcsLoginScreen'
import {vcsAnyGitProvider} from '../CreatePipelinePage/CreatePipelinePage.consts'
import CreatePipelineImageDark from '../CreatePipelinePage/Pipeline-dark.svg'
import CreatePipelineImageLight from '../CreatePipelinePage/Pipeline-light.svg'
import {usePipelineId, usePipelineParentProjectId} from '../hooks/pipeline'
import usePermissionCanEditPipeline from '../hooks/usePermissionCanEditPipeline'
import usePipelineDocumentTitle from '../hooks/usePipelineDocumentTitle'
import usePipelineVcsProviders from '../hooks/usePipelineVcsProviders'
import {getAccountRootProjectId} from '../PipelinesPages.consts'
import {pipelinesApi} from '../services/pipelinesApi'
import type {VcsProvider} from '../services/pipelinesApi.types'
import {VcsProviderType} from '../services/pipelinesApi.types'
import {isProjectsAndBuildTypesEnabled} from '../utils/featureToggles'

import type {AddRepositoryPageQuery} from './__generated__/AddRepositoryPageQuery.graphql'
import {query} from './AddRepositoryPage.queries'

import styles from './AddRepositoryPage.module.css'

type Queries = {
  main: AddRepositoryPageQuery
}

function AddRepositoryPage({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  const theme = useDarkOrLightTheme()
  const PipelineImage = theme === Theme.LIGHT ? CreatePipelineImageLight : CreatePipelineImageDark
  const navigate = useNavigate()
  const id = usePipelineId()
  const {canEditPipeline} = usePermissionCanEditPipeline()

  const {hasVcsRoot} = pipelinesApi.endpoints.getPipelineById.useQuery(id, {
    selectFromResult: ({data}) => ({hasVcsRoot: data?.vcsRoot != null}),
    refetchOnMountOrArgChange: true,
  })

  const {pipeline} = usePreloadedQuery(query, queries.main)
  const parentProjectId =
    usePipelineParentProjectId(pipeline?.parentProject ?? null) ?? getAccountRootProjectId()
  const {vcsProviders, authorizedProvider, getVcsProvidersRefetch} =
    usePipelineVcsProviders(parentProjectId)
  const [isSelectedAnyProvider, setIsSelectedAnyProvider] = useState(false)

  const buttonProviderLoginClickHandler = (value?: VcsProvider) => {
    if (value?.type === VcsProviderType.ANY) {
      setIsSelectedAnyProvider(true)
    } else {
      getVcsProvidersRefetch()
    }
  }

  usePipelineDocumentTitle('Add repository')

  if (hasVcsRoot) {
    return <Redirect to={getPipelineHref(id)} replace />
  }

  return (
    <RestScreenHeight>
      {canEditPipeline ? (
        <div className={styles.page}>
          {vcsProviders == null ? (
            <Loader />
          ) : (
            <>
              <IconButton
                className={styles.close}
                title={'Close'}
                icon={'close-20px'}
                onClick={() => navigate(getPipelineHref(id))}
              />
              {!isProjectsAndBuildTypesEnabled() &&
              authorizedProvider == null &&
              !isSelectedAnyProvider ? (
                <VcsLoginScreen
                  vcsProviders={vcsProviders}
                  onLogin={buttonProviderLoginClickHandler}
                />
              ) : (
                <div className={styles.container}>
                  <div className={styles.addRepository}>
                    <PageTitle className={classNames(styles.title)}>{'Add Repository'}</PageTitle>
                    <PipelineForm
                      key={parentProjectId} // Reset form when parentProjectId changes
                      vcsProviders={vcsProviders}
                      authorizedProvider={authorizedProvider ?? vcsAnyGitProvider}
                      onVcsLogin={
                        process.env.NODE_ENV !== 'test' ? getVcsProvidersRefetch : undefined
                      }
                      pipelineId={id}
                      projectId={parentProjectId}
                    />
                  </div>
                  <div className={styles.imageWrapper}>
                    <img alt="Create Pipeline" src={PipelineImage} width={460} height={460} />
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      ) : (
        <div className={styles.errorWrapper}>
          <ErrorMessage
            icon={lockIcon}
            message="Access denied"
            description="You do not have enough permissions to edit this pipeline"
          >
            <RouterLink to={getPipelinesHref()}>{'Go to the home page'}</RouterLink>
          </ErrorMessage>
        </div>
      )}
    </RestScreenHeight>
  )
}

export default AddRepositoryPage
export type AddRepositoryPageComponent = typeof AddRepositoryPage
